insert into public.products (id, category_id, name, description, price, sale_price, image, available, featured, rating, preparation_time, sort_order) values
  ('classic-zinger', 'burgers', 'Classic Zinger Burger', 'Crispy hand-breaded chicken fillet, crunchy lettuce and our signature mayo in a toasted sesame bun.', 399, null, 'photo:classic-zinger', true, true, 4.8, 12, 0),
  ('zinger-cheese', 'burgers', 'Cheese Burger', 'Crispy zinger fillet under a double layer of melted cheddar, pickles and house chilli sauce.', 469, null, 'photo:cheese-burger', true, false, 4.7, 12, 1),
  ('double-decker', 'burgers', 'Double Decker Zinger', 'Two crispy fillets, double cheese, jalapeños and smoky sauce stacked high.', 649, 599, 'photo:double-decker', true, true, 4.9, 15, 2),
  ('chicken-patty', 'burgers', 'Crispy Chicken Burger', 'Golden crumbed chicken breast, crisp iceberg, tomato and creamy garlic mayo in a brioche bun.', 349, null, 'photo:crispy-chicken-burger', true, false, 4.4, 10, 3),
  ('beef-smash', 'burgers', 'Double Beef Burger', 'Two smashed beef patties, double cheddar, caramelised onions and our tangy burger sauce.', 699, null, 'photo:double-beef-burger', true, true, 4.6, 14, 4),
  ('tower-burger', 'burgers', 'Special Loaded Burger', 'Our biggest build: zinger fillet, beef patty, hash brown, cheese, jalapeños and smoky sauce.', 849, null, 'photo:special-loaded-burger', true, true, 4.7, 16, 5),
  ('chicken-tikka-pizza', 'pizza', 'Chicken Tikka Pizza', 'Smoky tikka chicken, onions, capsicum and mozzarella on a hand-stretched base.', 650, null, 'photo:chicken-tikka-pizza', true, true, 4.7, 20, 0),
  ('chicken-fajita-pizza', 'pizza', 'Chicken Fajita Pizza', 'Fajita-spiced chicken, peppers, onions and plenty of cheese.', 650, null, 'photo:fajita-pizza', true, false, 4.6, 20, 1),
  ('malai-boti-pizza', 'pizza', 'Pepperoni Pizza', 'Halal chicken pepperoni, rich tomato sauce and a generous layer of mozzarella.', 699, null, 'photo:pepperoni-pizza', true, false, 4.6, 20, 2),
  ('crown-crust-pizza', 'pizza', 'AT Naveed Special Pizza', 'Crown crust stuffed with cheese, topped with tikka, fajita chicken, olives and peppers.', 1199, null, 'photo:special-pizza', true, false, 4.8, 25, 3),
  ('veggie-pizza', 'pizza', 'Cheese Lovers Pizza', 'Mozzarella, cheddar and parmesan over a garlic-butter base. Pure cheese pull.', 599, null, 'photo:cheese-lovers-pizza', true, false, 4.3, 18, 4),
  ('chicken-shawarma', 'shawarma', 'Chicken Shawarma', 'Juicy spiced chicken, garlic sauce, pickles and salad rolled in fresh pita.', 250, null, 'photo:chicken-shawarma', true, true, 4.7, 8, 0),
  ('zinger-shawarma', 'shawarma', 'Zinger Shawarma', 'Crispy zinger strips with spicy mayo and fresh salad, wrapped to go.', 320, null, 'photo:zinger-shawarma', true, false, 4.6, 10, 1),
  ('cheese-shawarma', 'shawarma', 'Cheese Shawarma', 'Classic chicken shawarma loaded with melted cheese.', 300, null, 'photo:cheese-shawarma', true, false, 4.5, 9, 2),
  ('shawarma-platter', 'shawarma', 'Special Shawarma Platter', 'Sliced chicken shawarma over rice with fries, salad, pickles, garlic sauce and pita.', 549, null, 'photo:special-shawarma', true, false, 4.7, 12, 3),
  ('crispy-chicken-2pc', 'fried-chicken', 'Fried Chicken Pieces (2 pcs)', 'Two pieces of golden, double-breaded chicken marinated overnight.', 450, null, 'photo:fried-chicken', true, true, 4.6, 15, 0),
  ('chicken-bucket', 'fried-chicken', 'Family Bucket (9 pcs)', 'Nine pieces of crispy fried chicken. Made for sharing.', 1899, 1749, 'photo:chicken-bucket', true, false, 4.8, 20, 1),
  ('hot-wings', 'fried-chicken', 'Crispy Chicken Wings (6 pcs)', 'Crunchy wings tossed in our house hot sauce, served with a cooling dip.', 399, null, 'photo:chicken-wings', true, false, 4.5, 12, 2),
  ('chicken-nuggets', 'fried-chicken', 'Chicken Nuggets (6 pcs)', 'Tender bite-sized nuggets with a dip of your choice.', 349, null, 'photo:chicken-nuggets', true, false, 4.4, 10, 3),
  ('chicken-strips', 'fried-chicken', 'Chicken Strips (5 pcs)', 'Hand-breaded strips of chicken breast, crispy outside and juicy inside.', 429, null, 'photo:chicken-strips', true, false, 4.6, 10, 4),
  ('regular-fries', 'fries-sides', 'Regular Fries', 'Golden, crispy and lightly salted.', 150, null, 'photo:regular-fries', true, false, 4.5, 6, 0),
  ('masala-fries', 'fries-sides', 'Masala Fries', 'Crispy fries tossed in our tangy chaat masala.', 199, null, 'photo:masala-fries', true, false, 4.6, 6, 1),
  ('cheese-fries', 'fries-sides', 'Cheese Fries', 'Crispy fries smothered in warm, velvety cheese sauce.', 299, null, 'photo:cheese-fries', true, false, 4.6, 6, 2),
  ('loaded-fries', 'fries-sides', 'Loaded Fries', 'Fries piled with cheese sauce, crispy chicken chunks, jalapeños and spicy mayo.', 449, null, 'photo:loaded-fries', true, true, 4.7, 8, 3),
  ('coleslaw', 'fries-sides', 'Creamy Coleslaw', 'Fresh cabbage and carrots in a light, creamy dressing.', 99, null, 'photo:coleslaw', true, false, 4.3, 2, 4),
  ('garlic-mayo-dip', 'fries-sides', 'Garlic Mayo Dip', 'Our house garlic mayo, perfect with everything.', 60, null, 'photo:garlic-mayo', true, false, 4.6, 1, 5),
  ('soft-drink', 'drinks', 'Cold Drink', 'Ice-cold fizzy drink of your choice.', 100, null, 'photo:cold-drink', true, false, 4.5, 1, 0),
  ('mint-margarita', 'drinks', 'Mint Margarita', 'Fresh mint, lemon and crushed ice blended to order.', 249, null, 'photo:mint-margarita', true, false, 4.7, 4, 1),
  ('fresh-juice', 'drinks', 'Fresh Juice', 'Freshly squeezed seasonal juice — orange, mango or apple.', 279, null, 'photo:fresh-juice', true, false, 4.7, 4, 2),
  ('chocolate-shake', 'drinks', 'Milkshake', 'Thick hand-spun shake topped with whipped cream.', 349, null, 'photo:milkshake', true, false, 4.6, 5, 3),
  ('mineral-water', 'drinks', 'Mineral Water', '500 ml bottled water.', 80, null, 'photo:mineral-water', true, false, 4.5, 1, 4),
  ('deal-zinger-combo', 'deals', 'Zinger Combo', 'Classic Zinger Burger, regular fries and a 345 ml drink.', 749, 699, 'photo:deal-zinger-combo', true, true, 4.8, 12, 0),
  ('deal-student', 'deals', 'Student Deal', 'Crispy Chicken Burger, regular fries and a 345 ml drink.', 499, null, 'photo:deal-student', true, false, 4.5, 10, 1),
  ('deal-shawarma-duo', 'deals', 'Shawarma Duo', 'Two Chicken Shawarmas, regular fries and two 345 ml drinks.', 849, 799, 'photo:deal-shawarma-duo', true, false, 4.6, 10, 2),
  ('deal-family-feast', 'deals', 'Family Feast', 'Medium pizza, 4 pcs fried chicken, 2 Zinger burgers, large fries and a 1.5 L drink.', 2899, 2599, 'photo:deal-family-feast', true, true, 4.9, 25, 3)
