insert into public.offers (id, title, description, type, value, code, min_order, product_id, image, badge, active) values
  ('offer-zinger-combo', 'Zinger + Fries + Drink', 'Our most-ordered combo for one, at a combo price.', 'combo', 699, null, 0, 'deal-zinger-combo', 'photo:deal-zinger-combo', 'Best value', true),
  ('offer-family-feast', 'Family Feast', 'Pizza, chicken, burgers, fries and a big drink for 4–5 people.', 'combo', 2599, null, 0, 'deal-family-feast', 'photo:deal-family-feast', 'Save Rs. 300', true),
  ('offer-pabbi10', '10% off your order', 'Use code PABBI10 on orders of Rs. 1,000 or more.', 'percentage', 10, 'PABBI10', 1000, null, 'photo:pepperoni-pizza', 'Promo code', true),
  ('offer-flat150', 'Rs. 150 off big orders', 'Taken off automatically when your order reaches Rs. 2,500.', 'fixed', 150, null, 2500, null, 'photo:chicken-bucket', 'Automatic', true),
  ('offer-shawarma-15', '15% off Chicken Shawarma', 'Every Chicken Shawarma is 15% off while this offer runs.', 'product_deal', 15, null, 0, 'chicken-shawarma', 'photo:chicken-shawarma', 'Limited time', true)
